// Classic-worker entry (esbuild IIFE). Laminate planner pattern:
// importScripts(z3-built.js) → wrap initZ3 with mainScriptUrlOrBlob + locateFile
// → z3-solver high-level init() → solveLeague. No JS placer in this file.
import { init as initHighLevel } from "z3-solver";
import { solveLeague } from "./solver.ts";

const GLUE_URL = new URL("./z3-built.js", self.location.href).href;

let z3ready;

async function loadZ3() {
  if (typeof SharedArrayBuffer === "undefined" || !self.crossOriginIsolated) {
    throw new Error(
      "Z3 needs SharedArrayBuffer — the page must be cross-origin isolated " +
        "(COOP: same-origin + COEP: require-corp headers).",
    );
  }
  if (typeof self.initZ3 !== "function") {
    self.global ||= self;
    importScripts(GLUE_URL);
    if (typeof self.initZ3 !== "function") {
      throw new Error("z3-built.js loaded but did not set initZ3");
    }
    const raw = self.initZ3;
    self.initZ3 = (mod) =>
      raw({
        mainScriptUrlOrBlob: GLUE_URL,
        locateFile: (path) => new URL(path, self.location.href).href,
        ...mod,
      });
  }
  return (z3ready ??= initHighLevel());
}

self.onmessage = async (e) => {
  const { id, league, name } = e.data || {};
  try {
    const res = await solveLeague(league, name, loadZ3);
    self.postMessage({ id, ok: true, res });
  } catch (err) {
    self.postMessage({ id, ok: false, error: String((err && err.message) || err) });
  }
};
