/** Crow-flies minutes. Never billed as driving. */

const R_KM = 6371;
const KM_PER_MILE = 1.60934;
const MPH = 40; // unhurried van, as the crow flies — labeled as such

function toRad(d: number): number {
  return (d * Math.PI) / 180;
}

export function haversineMiles(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number {
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const la1 = toRad(a.lat);
  const la2 = toRad(b.lat);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(la1) * Math.cos(la2) * Math.sin(dLng / 2) ** 2;
  const km = 2 * R_KM * Math.asin(Math.min(1, Math.sqrt(h)));
  return km / KM_PER_MILE;
}

export function crowFliesMinutes(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number {
  const miles = haversineMiles(a, b);
  return Math.max(1, Math.round((miles / MPH) * 60));
}
