/** Human date phrases from the Season sheet. Never invent a Saturday from nonsense. */

const MONTHS: Record<string, number> = {
  january: 1, february: 2, march: 3, april: 4, may: 5, june: 6,
  july: 7, august: 8, september: 9, october: 10, november: 11, december: 12,
  jan: 1, feb: 2, mar: 3, apr: 4, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9,
  oct: 10, nov: 11, dec: 12,
};

const WEEKDAYS = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];

export function iso(y: number, m: number, d: number): string {
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

export function parseIso(s: string): Date {
  const [y, m, d] = s.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d));
}

export function addDays(isoDate: string, n: number): string {
  const dt = parseIso(isoDate);
  dt.setUTCDate(dt.getUTCDate() + n);
  return iso(dt.getUTCFullYear(), dt.getUTCMonth() + 1, dt.getUTCDate());
}

export function weekdayName(isoDate: string): string {
  return WEEKDAYS[parseIso(isoDate).getUTCDay()];
}

export function formatLong(isoDate: string): string {
  const dt = parseIso(isoDate);
  const wd = WEEKDAYS[dt.getUTCDay()];
  const months = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
  ];
  const name = wd[0].toUpperCase() + wd.slice(1);
  return `${name}, ${months[dt.getUTCMonth()]} ${dt.getUTCDate()}`;
}

export function inferYear(title: string, fallback = 2026): number {
  const m = String(title || "").match(/20\d{2}/);
  return m ? Number(m[0]) : fallback;
}

export function parseSeasonTitle(raw: string): string {
  const s = String(raw || "").trim();
  if (!s) return "";
  const m = s.match(/(fall|spring|summer|winter)?\s*(20\d{2})\s*(?:to|-|–|—)\s*(20\d{2})/i);
  if (m) {
    const season = m[1] ? m[1][0].toUpperCase() + m[1].slice(1).toLowerCase() + " " : "";
    return `${season}${m[2]}–${m[3]}`;
  }
  return s.replace(/\s+to\s+/i, "–");
}

/** Clock like 8:30, 18:00, 6:30 pm → minutes from midnight. */
export function parseClock(raw: string): number | null {
  const s = String(raw || "").trim().toLowerCase();
  if (!s) return null;
  const m = s.match(/^(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?$/i);
  if (!m) return null;
  let h = Number(m[1]);
  const min = m[2] ? Number(m[2]) : 0;
  const ap = (m[3] || "").replace(/\./g, "");
  if (ap.startsWith("p") && h < 12) h += 12;
  if (ap.startsWith("a") && h === 12) h = 0;
  if (h > 23 || min > 59) return null;
  return h * 60 + min;
}

export function formatClock(minutes: number): string {
  const h24 = Math.floor(minutes / 60) % 24;
  const min = minutes % 60;
  const ap = h24 >= 12 ? "p.m." : "a.m.";
  let h = h24 % 12;
  if (h === 0) h = 12;
  return `${h}:${String(min).padStart(2, "0")}`;
}

/** Spreadsheet date like 6-Sep. */
export function formatSheetDate(isoDate: string): string {
  const dt = parseIso(isoDate);
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return `${dt.getUTCDate()}-${months[dt.getUTCMonth()]}`;
}

/** Spreadsheet time like 11:00AM. Empty → TBA. */
export function formatSheetTime(raw: string): string {
  const s = String(raw || "").trim();
  if (!s || /^tba$/i.test(s)) return "TBA";
  const mins = parseClock(s);
  if (mins == null) return s.replace(/\s+/g, "") || "TBA";
  const h24 = Math.floor(mins / 60) % 24;
  const min = mins % 60;
  const ap = h24 >= 12 ? "PM" : "AM";
  let h = h24 % 12;
  if (h === 0) h = 12;
  return `${h}:${String(min).padStart(2, "0")}${ap}`;
}

export function formatClockShort(minutes: number): string {
  const h24 = Math.floor(minutes / 60) % 24;
  const min = minutes % 60;
  return `${h24}:${String(min).padStart(2, "0")}`;
}

/**
 * Parse a commissioner date. Year comes from the season title.
 * Returns null when the phrase is not a date — caller must not invent one.
 */
export function parseHumanDate(raw: string, year: number): string | null {
  const s = String(raw || "").replace(/\s+/g, " ").trim();
  if (!s) return null;
  const isoMatch = s.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);
  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;

  const range = s.match(
    /\b([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?\s*[–—-]\s*(\d{1,2})(?:st|nd|rd|th)?\b/,
  );
  if (range && MONTHS[range[1].toLowerCase()]) {
    return iso(year, MONTHS[range[1].toLowerCase()], Number(range[2]));
  }

  const long = s.match(
    /\b(?:sunday|monday|tuesday|wednesday|thursday|friday|saturday)?\s*,?\s*([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,\s*(20\d{2}))?\b/i,
  );
  if (long && MONTHS[long[1].toLowerCase()]) {
    const y = long[3] ? Number(long[3]) : year;
    const month = MONTHS[long[1].toLowerCase()];
    const day = Number(long[2]);
    if (day >= 1 && day <= 31) return iso(y, month, day);
  }

  const numeric = s.match(/\b(\d{1,2})\/(\d{1,2})\/(20\d{2})\b/);
  if (numeric) return iso(Number(numeric[3]), Number(numeric[1]), Number(numeric[2]));

  return null;
}

/** "October 10–12" → each day. A single date is a one-element list. */
export function expandVacationDays(raw: string | undefined, year: number): string[] {
  if (!raw) return [];
  const s = String(raw).replace(/\s+/g, " ").trim();
  const range = s.match(
    /\b([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?\s*[–—-]\s*(\d{1,2})(?:st|nd|rd|th)?\b/,
  );
  if (range && MONTHS[range[1].toLowerCase()]) {
    const month = MONTHS[range[1].toLowerCase()];
    const a = Number(range[2]);
    const b = Number(range[3]);
    const out: string[] = [];
    for (let d = Math.min(a, b); d <= Math.max(a, b); d++) out.push(iso(year, month, d));
    return out;
  }
  const one = parseHumanDate(s, year);
  return one ? [one] : [];
}

export function vacationCovers(raw: string | undefined, isoDate: string, year: number): boolean {
  const days = expandVacationDays(raw, year);
  if (days.includes(isoDate)) return true;
  return days.some((d) => {
    const diff = Math.abs(Date.parse(d + "T00:00:00Z") - Date.parse(isoDate + "T00:00:00Z")) / 86400000;
    return diff <= 2;
  });
}

export function looksLikeDateAttempt(raw: string): boolean {
  const s = String(raw || "").toLowerCase();
  if (!s) return false;
  if (/satuday|fifthish|tommorrow|whenever|ish\b/.test(s)) return true;
  if (/\b(mon|tue|wed|thu|fri|sat|sun|january|february|march|april|june|july|august|september|october|november|december)/i.test(s)) {
    return true;
  }
  return /\d/.test(s) && /day|week|date/i.test(s);
}

export function thanksgivingSaturday(year: number): string {
  // Fourth Thursday in November, then the Saturday of that week (Sat after).
  let d = new Date(Date.UTC(year, 10, 1));
  const thursdays: Date[] = [];
  while (d.getUTCMonth() === 10) {
    if (d.getUTCDay() === 4) thursdays.push(new Date(d));
    d.setUTCDate(d.getUTCDate() + 1);
  }
  const t = thursdays[3] || thursdays[thursdays.length - 1];
  const sat = new Date(t);
  sat.setUTCDate(t.getUTCDate() + 2);
  return iso(sat.getUTCFullYear(), sat.getUTCMonth() + 1, sat.getUTCDate());
}

export function saturdaysInclusive(firstIso: string, lastIso: string, weekStarts = "Saturday"): string[] {
  const out: string[] = [];
  const { start } = weekBounds(firstIso, weekStarts || "Saturday");
  let sat = start;
  while (weekdayName(sat) !== "saturday") sat = addDays(sat, 1);
  if (sat > lastIso) return out;
  for (let d = sat; d <= lastIso; d = addDays(d, 7)) out.push(d);
  return out;
}

export function formatSpan(startIso: string, endIso: string): string {
  const a = parseIso(startIso);
  const b = parseIso(endIso);
  const months = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
  ];
  const ma = months[a.getUTCMonth()];
  const mb = months[b.getUTCMonth()];
  if (ma === mb) return `${ma} ${a.getUTCDate()}–${b.getUTCDate()}`;
  return `${ma} ${a.getUTCDate()} – ${mb} ${b.getUTCDate()}`;
}

export function weekBounds(dateIso: string, weekStarts: string): { start: string; end: string } {
  const startName = weekStarts.trim().toLowerCase();
  const startIdx = WEEKDAYS.indexOf(startName);
  const dow = parseIso(dateIso).getUTCDay();
  const back = startIdx < 0 ? dow : (dow - startIdx + 7) % 7;
  const start = addDays(dateIso, -back);
  return { start, end: addDays(start, 6) };
}

export function parseVacationRange(raw: string, year: number): { start?: string; end?: string; label: string } {
  const label = String(raw || "").trim();
  if (!label) return { label: "" };
  const m = label.match(
    /([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?\s*[–—-]\s*(\d{1,2})(?:st|nd|rd|th)?/,
  );
  if (m && MONTHS[m[1].toLowerCase()]) {
    const start = iso(year, MONTHS[m[1].toLowerCase()], Number(m[2]));
    const end = iso(year, MONTHS[m[1].toLowerCase()], Number(m[3]));
    return { start, end, label };
  }
  const one = parseHumanDate(label, year);
  return { start: one || undefined, end: one || undefined, label };
}

export function dateInRange(isoDate: string, start?: string, end?: string): boolean {
  if (!start) return false;
  if (!end) return isoDate === start;
  return isoDate >= start && isoDate <= end;
}

export function parseAvailability(raw: string): { day: string; startMinutes: number; endMinutes: number }[] {
  const s = String(raw || "").trim();
  if (!s) return [];
  const windows: { day: string; startMinutes: number; endMinutes: number }[] = [];
  const chunks = s.split(/;|\n/).map((c) => c.trim()).filter(Boolean);
  for (const chunk of chunks) {
    const m = chunk.match(
      /^(sunday|monday|tuesday|wednesday|thursday|friday|saturday)\s+(\d{1,2}(?::\d{2})?\s*(?:a\.?m\.?|p\.?m\.?)?)\s*[–—-]\s*(\d{1,2}(?::\d{2})?\s*(?:a\.?m\.?|p\.?m\.?)?)/i,
    );
    if (!m) continue;
    const start = parseClock(m[2]);
    const end = parseClock(m[3]);
    if (start == null || end == null) continue;
    windows.push({ day: m[1].toLowerCase(), startMinutes: start, endMinutes: end });
  }
  return windows;
}
