import type { League, PlayingWeek, SpecialDate } from "./model";
import {
  addDays,
  inferYear,
  parseHumanDate,
  saturdaysInclusive,
  thanksgivingSaturday,
  weekBounds,
  weekdayName,
} from "./dates";

export function seasonYear(league: League): number {
  return inferYear(league.season.title || league.season.headerTitle, 2026);
}

export function playingSaturdays(league: League): string[] {
  const first = league.season.firstIso;
  const last = league.season.lastIso;
  if (!first || !last) return [];
  return saturdaysInclusive(first, last, league.season.weekStarts || "Saturday");
}

export function byeIsos(league: League): Set<string> {
  const year = seasonYear(league);
  const set = new Set<string>();
  for (const s of league.season.specials) {
    if (s.kind !== "bye") continue;
    if (s.iso) {
      // if bye is a weekday, snap to that week's Saturday in a Saturday-start season
      set.add(snapToSaturday(s.iso, league.season.weekStarts));
      continue;
    }
    if (/thanksgiving/i.test(s.raw + " " + (s.note || ""))) {
      const t = thanksgivingSaturday(year);
      const sats = playingSaturdays(league);
      const inRange = sats.find((d) => d === t) || sats.filter((d) => d <= t).pop();
      if (inRange) set.add(inRange);
    }
  }
  return set;
}

export function rainCheckIsos(league: League): string[] {
  return league.season.specials
    .filter((s) => s.kind === "rain-check" && s.iso)
    .map((s) => s.iso!) ;
}

function snapToSaturday(isoDate: string, weekStarts: string): string {
  if (weekdayName(isoDate) === "saturday") return isoDate;
  const { start } = weekBounds(isoDate, weekStarts || "Saturday");
  let d = start;
  for (let i = 0; i < 7; i++) {
    if (weekdayName(d) === "saturday") return d;
    d = addDays(d, 1);
  }
  return isoDate;
}

export function weeks(league: League): PlayingWeek[] {
  const sats = playingSaturdays(league);
  const byes = byeIsos(league);
  const rains = new Set(rainCheckIsos(league));
  const startName = league.season.weekStarts || "Saturday";
  const out: PlayingWeek[] = sats.map((sat) => {
    const { start, end } = weekBounds(sat, startName);
    const isBye = byes.has(sat);
    return {
      startIso: start,
      endIso: end,
      label: sat,
      kind: isBye ? "bye" : "playing",
      saturdays: [sat],
    };
  });
  for (const r of rains) {
    if (out.some((w) => w.saturdays.includes(r))) continue;
    const { start, end } = weekBounds(r, startName);
    out.push({
      startIso: start,
      endIso: end,
      label: r,
      kind: "rain-check",
      saturdays: [r],
    });
  }
  out.sort((a, b) => a.label.localeCompare(b.label));
  return out;
}

export function owedGames(league: League): number {
  return weeks(league).filter((w) => w.kind === "playing").length;
}

export function resolveSpecial(raw: string, kind: SpecialDate["kind"], year: number): SpecialDate {
  const note = raw;
  if (/thanksgiving/i.test(raw) && kind === "bye") {
    return { kind, raw, iso: undefined, note };
  }
  const iso = parseHumanDate(raw, year);
  if (iso) return { kind, raw, iso, note };
  return { kind, raw, note };
}
