/**
 * Whole-season Z3 objective. Same terms the optimizer minimizes across
 * every playing week — not last Saturday. Hard: legal fields, refs, travel,
 * hours, roster. Soft: rematch cap, grass rank, travel minutes, household/car.
 * Evaluating a sitting is instant (no new SMT). Diversity lives in diversity.ts.
 */

import { findTeam, withheldMatchups } from "./carve";
import { parseClock, weekdayName } from "./dates";
import { scoreSeasonDiversity } from "./diversity";
import {
  norm,
  teamLabel,
  type Configuration,
  type League,
  type PlacedGame,
  type Team,
  type Z3SeasonScore,
} from "./model";
import { travelMinutes } from "./validate";

const HARD = 10_000;
const REMATCH = 80;
const HOUSEHOLD = 40;
const TRAVEL_MIN = 1;

function clockOr(s: string, fallback: number): number {
  let n = parseClock(s) ?? fallback;
  if (n < 7 * 60) n += 12 * 60;
  return n;
}

function fieldShort(name: string): string {
  const m = name.match(/Field\s+([A-Z])/i);
  if (m) return `Field ${m[1].toUpperCase()}`;
  if (/stadium/i.test(name)) return name;
  return name;
}

export function findField(league: League, raw: string): League["fields"][number] | undefined {
  const n = norm(raw);
  if (!n) return undefined;
  return (
    league.fields.find((f) => norm(f.name) === n) ||
    league.fields.find((f) => norm(fieldShort(f.name)) === n) ||
    league.fields.find((f) => norm(f.name).endsWith(n) || n.endsWith(norm(fieldShort(f.name))))
  );
}

function grassRank(league: League, bracket: string, kickoff: string, day: string): number {
  const minutes = clockOr(kickoff, 9 * 60);
  const hits = league.preferredSlots
    .filter((p) => norm(p.bracket) === norm(bracket) && p.day.toLowerCase() === day.toLowerCase())
    .sort((a, b) => a.rank - b.rank);
  const hit = hits.find((p) => clockOr(p.time, -1) === minutes);
  if (!hit) return 40;
  return (hit.rank - 1) * 8;
}

function fieldOpenAt(field: League["fields"][number], dayName: string, kick: number, vacate: number): boolean {
  const win = field.windows.find((w) => w.day === dayName);
  if (field.windows.length && !win) return false;
  if (win && (kick < win.startMinutes || vacate > win.endMinutes + 5)) return false;
  return true;
}

function legalFieldFor(league: League, game: PlacedGame, field: League["fields"][number]): boolean {
  const ag = league.ageGroups.find((a) => norm(a.name) === norm(game.ageGroup));
  if (!ag) return true;
  return ag.fieldClasses.some((c) => norm(c) === norm(field.type));
}

function windowsOverlap(a0: number, a1: number, b0: number, b1: number): boolean {
  return !(a1 <= b0 || b1 <= a0);
}

function teamOn(g: PlacedGame, label: string): boolean {
  return g.home === label || g.away === label;
}

function householdCost(league: League, games: PlacedGame[]): number {
  let cost = 0;
  for (const f of league.families) {
    if (f.children.length < 2) continue;
    const dates = [...new Set(games.map((g) => g.dateIso))];
    for (const date of dates) {
      const stops: { kick: number; vacate: number; campus: string }[] = [];
      for (const c of f.children) {
        const t = league.teams.find((x) => x.name === c.team && x.bracket === c.bracket);
        const label = t ? teamLabel(t) : `${c.bracket} ${c.team}`;
        const g = games.find((x) => x.dateIso === date && teamOn(x, label));
        if (!g) continue;
        stops.push({
          kick: clockOr(g.kickoff, 10 * 60),
          vacate: clockOr(g.vacate, clockOr(g.end, 11 * 60)),
          campus: g.campus,
        });
      }
      for (let i = 0; i < stops.length; i++) {
        for (let j = i + 1; j < stops.length; j++) {
          if (!windowsOverlap(stops[i].kick - 15, stops[i].vacate, stops[j].kick - 15, stops[j].vacate)) continue;
          cost += norm(stops[i].campus) === norm(stops[j].campus) ? HOUSEHOLD / 2 : HOUSEHOLD;
        }
      }
    }
  }
  return cost;
}

function coachTravelHard(league: League, games: PlacedGame[]): number {
  let n = 0;
  const byCoach = new Map<string, PlacedGame[]>();
  for (const t of league.teams) {
    if (!t.coach) continue;
    const who = `${t.coach.first} ${t.coach.last}`.trim();
    const label = teamLabel(t);
    for (const g of games) {
      if (!teamOn(g, label)) continue;
      byCoach.set(who, [...(byCoach.get(who) || []), g]);
    }
  }
  for (const list of byCoach.values()) {
    const sorted = [...list].sort((a, b) => a.dateIso.localeCompare(b.dateIso) || clockOr(a.kickoff, 0) - clockOr(b.kickoff, 0));
    for (let i = 1; i < sorted.length; i++) {
      if (sorted[i].dateIso !== sorted[i - 1].dateIso) continue;
      const prev = sorted[i - 1];
      const next = sorted[i];
      const travel = travelMinutes(league, prev.campus, next.campus).minutes ?? 0;
      const ready = clockOr(prev.vacate, 0) + (norm(prev.campus) === norm(next.campus) ? 0 : travel);
      if (ready > clockOr(next.warmupStart, clockOr(next.kickoff, 0) - 15)) n += 1;
    }
  }
  return n;
}

function rematchCost(league: League, games: PlacedGame[]): { cost: number; byBracket: Map<string, number> } {
  const cap = league.season.rematchCap || 2;
  const withheld = new Set(withheldMatchups(league).map((w) => [w.a, w.b].sort().join("|")));
  const tally = new Map<string, { n: number; bracket: string }>();
  for (const g of games) {
    const k = [g.home, g.away].sort().join("|");
    const cur = tally.get(k) || { n: 0, bracket: g.ageGroup };
    cur.n += 1;
    tally.set(k, cur);
  }
  let cost = 0;
  const byBracket = new Map<string, number>();
  for (const [k, { n, bracket }] of tally) {
    if (withheld.has(k)) cost += HARD * n;
    const extra = Math.max(0, n - cap);
    const add = extra * REMATCH;
    cost += add;
    byBracket.set(bracket, (byBracket.get(bracket) || 0) + add);
  }
  return { cost, byBracket };
}

export interface FiatFill {
  window: string;
  dateIso?: string;
  kind: string;
  best: string;
  why: string;
}

/** External / fiat windows — which side fills them best across the fall. */
export function whoFillsFiat(league: League, games: PlacedGame[]): FiatFill[] {
  const out: FiatFill[] = [];
  const rank = (t: Team, day: string) => {
    const hits = league.preferredSlots
      .filter((p) => norm(p.bracket) === norm(t.bracket) && p.day.toLowerCase() === day)
      .sort((a, b) => a.rank - b.rank);
    return hits[0]?.rank ?? 40;
  };
  for (const s of league.season.specials) {
    if (s.kind !== "interleague-home" && s.kind !== "interleague-away") continue;
    const day = s.iso ? weekdayName(s.iso) : "saturday";
    const guest = s.kind === "interleague-home";
    const ranked = [...league.teams].sort((a, b) => {
      const da = guest ? b.guestDesired - a.guestDesired : b.awayDesired - a.awayDesired;
      if (da) return da;
      return rank(a, day) - rank(b, day);
    });
    const placed = s.iso ? games.filter((g) => g.dateIso === s.iso) : [];
    const sitting = ranked.find((t) => placed.some((g) => teamOn(g, teamLabel(t))));
    const best = sitting || ranked[0];
    const label = best ? teamLabel(best) : "no side asked";
    const why = guest
      ? `${label} fills best across the season — guest window at home, rank-${rank(best || ranked[0], day)} grass`
      : `${label} fills best across the season — away window, travel they already asked for`;
    out.push({
      window: s.iso || s.raw,
      dateIso: s.iso,
      kind: s.kind,
      best: label,
      why,
    });
  }
  for (const c of league.carveOuts) {
    if (!c.mustUse && !c.notAt) continue;
    out.push({
      window: `${c.team} ${c.mustUse ? `must ${c.mustUse}` : `not ${c.notAt}`}`,
      kind: "fiat-slot",
      best: c.team,
      why: c.mustUse
        ? `${c.team} fills the locked ${c.mustUse} window`
        : `${c.team} yields ${c.notAt} — the next rank fills it`,
    });
  }
  return out;
}

export function scoreSeasonZ3(league: League, games: PlacedGame[]): Z3SeasonScore {
  const rem = rematchCost(league, games);
  let hard = 0;
  let grass = 0;
  let travel = 0;
  const house = householdCost(league, games);
  hard += coachTravelHard(league, games) * HARD;

  const byBracket = new Map<
    string,
    { cost: number; rematch: number; grass: number; travel: number; household: number; games: number; hard: number }
  >();
  const bump = (bracket: string) => {
    const row = byBracket.get(bracket) || {
      cost: 0,
      rematch: 0,
      grass: 0,
      travel: 0,
      household: 0,
      games: 0,
      hard: 0,
    };
    byBracket.set(bracket, row);
    return row;
  };

  const weekOf = new Map<string, PlacedGame[]>();
  for (const g of games) {
    const key = `${g.weekIso || g.dateIso}|${g.home}`;
    const keyB = `${g.weekIso || g.dateIso}|${g.away}`;
    weekOf.set(key, [...(weekOf.get(key) || []), g]);
    weekOf.set(keyB, [...(weekOf.get(keyB) || []), g]);
  }
  for (const list of weekOf.values()) {
    if (list.length > 1) hard += HARD * (list.length - 1);
  }

  for (const g of games) {
    const row = bump(g.ageGroup);
    row.games += 1;
    const field = findField(league, g.field);
    const day = weekdayName(g.dateIso);
    const kick = clockOr(g.kickoff, 10 * 60);
    const vacate = clockOr(g.vacate, kick + 60);
    if (field && !legalFieldFor(league, g, field)) {
      hard += HARD;
      row.hard += HARD;
    }
    if (field && !fieldOpenAt(field, day, kick, vacate)) {
      hard += HARD;
      row.hard += HARD;
    }
    if (!g.center && !league.season.proceedWithoutStaff) {
      hard += HARD;
      row.hard += HARD;
    }
    const gGrass = grassRank(league, g.ageGroup, g.kickoff, day);
    grass += gGrass;
    row.grass += gGrass;
    const home = findTeam(league, g.home);
    const homeCampus =
      (home && league.associations.find((a) => norm(a.name) === norm(home.association))?.homeCampus) || "Van Complex";
    if (norm(g.campus) !== norm(homeCampus)) {
      const mins = travelMinutes(league, homeCampus, g.campus).minutes ?? 30;
      travel += mins * TRAVEL_MIN;
      row.travel += mins * TRAVEL_MIN;
    }
  }

  const fieldDay = new Map<string, PlacedGame[]>();
  for (const g of games) {
    const k = `${g.dateIso}|${g.field}|${g.campus}`;
    fieldDay.set(k, [...(fieldDay.get(k) || []), g]);
  }
  for (const list of fieldDay.values()) {
    for (let i = 0; i < list.length; i++) {
      for (let j = i + 1; j < list.length; j++) {
        const a0 = clockOr(list[i].warmupStart, clockOr(list[i].kickoff, 0) - 15);
        const a1 = clockOr(list[i].vacate, clockOr(list[i].end, 0));
        const b0 = clockOr(list[j].warmupStart, clockOr(list[j].kickoff, 0) - 15);
        const b1 = clockOr(list[j].vacate, clockOr(list[j].end, 0));
        if (windowsOverlap(a0, a1, b0, b1)) hard += HARD;
      }
    }
  }

  for (const [bracket, add] of rem.byBracket) {
    bump(bracket).rematch += add;
  }
  const houseShare = byBracket.size || 1;
  for (const row of byBracket.values()) {
    row.household = Math.round(house / houseShare);
    row.cost = row.hard + row.rematch + row.grass + row.travel + row.household;
  }

  const cost = hard + rem.cost + grass + travel + house;
  const score = Math.max(0, 20_000 - rem.cost - grass - travel - house - Math.min(hard, 5_000));
  const brackets = [...byBracket.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([bracket, r]) => ({
      bracket,
      cost: r.cost,
      rematch: r.rematch,
      grass: r.grass,
      travel: r.travel,
      household: r.household,
      games: r.games,
      text: `${bracket}: ${r.cost} (rematch ${r.rematch}, grass ${r.grass}, travel ${r.travel})`,
    }));
  const bits = brackets.map((b) => `${b.bracket} ${b.cost}`).join(" · ");
  const text = `Z3 season: ${score} (cost ${cost} · whole fall) · ${bits || "no games"}`;
  return {
    scope: "season",
    cost,
    score,
    hardHeld: hard === 0,
    rematchCost: rem.cost,
    grassCost: grass,
    travelCost: travel,
    householdCost: house,
    hardCost: hard,
    brackets,
    text,
  };
}

export function stampSeasonScores(league: League, cfg: Configuration): Configuration {
  const z3 = scoreSeasonZ3(league, cfg.games);
  const diversity = scoreSeasonDiversity(league, cfg.games);
  cfg.z3Season = z3;
  cfg.diversity = diversity;
  cfg.scores = cfg.scores.filter((s) => s.key !== "z3" && s.key !== "diversity" && !s.key.startsWith("z3-"));
  const head = [{ key: "z3", text: z3.text }, { key: "diversity", text: diversity.text }];
  const rest = cfg.scores;
  cfg.scores = [...head, ...rest];
  for (const b of z3.brackets) {
    cfg.scores.push({ key: `z3-${norm(b.bracket).replace(/\s+/g, "-")}`, text: b.text });
  }
  return cfg;
}

export const FOUR_TENU = ["10U Hedgehogs", "10U Hawks", "10U Comets", "10U Bolts"] as const;

function tenUGame(
  id: string,
  dateIso: string,
  home: string,
  away: string,
  kickoff = "10:00",
  field = "Field C",
): PlacedGame {
  const kick = clockOr(kickoff, 10 * 60);
  const pad = (m: number) => {
    const h = Math.floor(m / 60);
    const min = m % 60;
    return `${h}:${String(min).padStart(2, "0")}`;
  };
  return {
    id,
    weekIso: dateIso,
    dateIso,
    kickoff,
    end: pad(kick + 60),
    warmupStart: pad(kick - 15),
    vacate: pad(kick + 70),
    ageGroup: "10U",
    home,
    away,
    field,
    campus: "Van Complex",
    parking: "Lot East",
    center: "Alex Reed",
    assistants: [],
    notes: [],
  };
}

/** Perfect Saturdays, same A-vs-B every week — a lumped fall. */
export function lumpedTenUSeason(dates: string[]): PlacedGame[] {
  const out: PlacedGame[] = [];
  dates.forEach((d, i) => {
    out.push(tenUGame(`lump-a-${i}`, d, FOUR_TENU[0], FOUR_TENU[1]));
    out.push(tenUGame(`lump-b-${i}`, d, FOUR_TENU[2], FOUR_TENU[3], "11:15", "Field D"));
  });
  return out;
}

/** Circle rotation — every pair meets before anyone rematches. */
export function spreadTenUSeason(dates: string[]): PlacedGame[] {
  const t = [...FOUR_TENU];
  const rounds: [string, string][][] = [
    [
      [t[0], t[1]],
      [t[2], t[3]],
    ],
    [
      [t[0], t[2]],
      [t[1], t[3]],
    ],
    [
      [t[0], t[3]],
      [t[1], t[2]],
    ],
  ];
  const out: PlacedGame[] = [];
  dates.forEach((d, i) => {
    const round = rounds[i % rounds.length];
    out.push(tenUGame(`spread-a-${i}`, d, round[0][0], round[0][1]));
    out.push(tenUGame(`spread-b-${i}`, d, round[1][0], round[1][1], "11:15", "Field D"));
  });
  return out;
}

export function ensureFourTenU(league: League): League {
  const have = new Set(league.teams.map((t) => teamLabel(t)));
  const proto = league.teams.find((t) => t.bracket === "10U");
  if (!proto) return league;
  for (const label of FOUR_TENU) {
    if (have.has(label)) continue;
    const name = label.replace(/^10U\s+/, "");
    league.teams.push({
      ...proto,
      name,
      jersey: name === "Comets" ? "ice blue" : "navy",
      coach: {
        first: name,
        last: "TenU",
        phone: name === "Comets" ? "903-555-0401" : "903-555-0403",
      },
      players: proto.players.map((p) => ({ ...p, name: `${name} ${p.name}` })),
      willNotPlay: [],
      willNotTravelTo: [],
    });
  }
  return league;
}
