/** Commissioner carve-outs and named matchup bans. Display + scoring, not SMT. */

import { playingSaturdays, seasonYear } from "./calendar";
import { addDays, parseClock, parseHumanDate, weekdayName } from "./dates";
import {
  norm,
  teamLabel,
  type CarveOut,
  type Configuration,
  type League,
  type PlacedGame,
  type ScoreLine,
  type Team,
} from "./model";

export function findTeam(league: League, raw: string): Team | undefined {
  const nraw = norm(raw);
  if (!nraw) return undefined;
  const exact = league.teams.find((t) => norm(teamLabel(t)) === nraw);
  if (exact) return exact;
  const named = league.teams.filter((t) => norm(t.name) === nraw);
  return named.length === 1 ? named[0] : undefined;
}

export function namesTeam(raw: string, t: Team): boolean {
  const nraw = norm(raw);
  return nraw === norm(teamLabel(t)) || nraw === norm(`${t.bracket} ${t.name}`);
}

export function withheldMatchups(league: League): { a: string; b: string }[] {
  const seen = new Set<string>();
  const out: { a: string; b: string }[] = [];
  for (const t of league.teams) {
    for (const w of t.willNotPlay) {
      const other = findTeam(league, w);
      if (!other || teamLabel(other) === teamLabel(t)) continue;
      const pair = [teamLabel(t), teamLabel(other)].sort();
      const key = pair.join("|");
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({ a: pair[0], b: pair[1] });
    }
  }
  return out;
}

export function playRefusalLabels(league: League, t: Team): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  const add = (w: string) => {
    const k = norm(w);
    if (!k || seen.has(k)) return;
    seen.add(k);
    out.push(w);
  };
  for (const w of t.willNotPlay) add(w);
  for (const other of league.teams) {
    if (teamLabel(other) === teamLabel(t)) continue;
    if (other.willNotPlay.some((w) => namesTeam(w, t))) add(teamLabel(other));
  }
  return out;
}

export function snapCarveDate(league: League, raw?: string): string | undefined {
  if (!raw) return undefined;
  const parsed = parseHumanDate(raw, seasonYear(league));
  if (!parsed) return undefined;
  const sats = playingSaturdays(league);
  if (sats.includes(parsed)) return parsed;
  let d = parsed;
  for (let i = 0; i < 7; i++) {
    if (weekdayName(d) === "saturday") break;
    d = addDays(d, -1);
  }
  if (sats.includes(d)) return d;
  return sats.find((s) => Math.abs(Date.parse(`${s}T00:00:00Z`) - Date.parse(`${parsed}T00:00:00Z`)) <= 2 * 86400000) || parsed;
}

export function carveDateShort(c: CarveOut): string {
  const raw = c.date || "";
  const m = raw.match(/([A-Za-z]+)\s+(\d{1,2})/);
  if (m) {
    const month = m[1][0].toUpperCase() + m[1].slice(1).toLowerCase();
    return `${month} ${m[2]}`;
  }
  return raw;
}

export function carveChipLabel(c: CarveOut): string {
  if (c.everySaturday && c.mustUse) return `every Saturday: must ${c.mustUse}`;
  const day = carveDateShort(c);
  if (c.notAt && day) return `${day}: not ${c.notAt}`;
  if (c.mustUse && day) return `${day}: must ${c.mustUse}`;
  if (c.notAt) return `not ${c.notAt}`;
  if (c.mustUse) return `must ${c.mustUse}`;
  return [c.team, day].filter(Boolean).join(" ");
}

export function carveOutsForTeam(league: League, t: Team): CarveOut[] {
  return league.carveOuts.filter((c) => {
    const hit = findTeam(league, c.team);
    return hit ? teamLabel(hit) === teamLabel(t) : namesTeam(c.team, t);
  });
}

function clock(raw: string): number {
  return parseClock(raw) ?? -1;
}

export function rematchTally(games: PlacedGame[]): Map<string, number> {
  const m = new Map<string, number>();
  for (const g of games) {
    const k = [g.home, g.away].sort().join(" vs ");
    m.set(k, (m.get(k) || 0) + 1);
  }
  return m;
}

export function matchupScoreLines(league: League, games: PlacedGame[]): { scores: ScoreLine[]; diagnostics: string[] } {
  const withheld = withheldMatchups(league);
  const scores: ScoreLine[] = [];
  const diagnostics: string[] = [];
  for (const w of withheld) {
    scores.push({ key: "withheld", text: `Matchup withheld: ${w.a} vs ${w.b}` });
  }
  if (!withheld.length) return { scores, diagnostics };
  const tally = rematchTally(games);
  const cap = league.season.rematchCap || 2;
  const extra = [...tally.entries()].filter(([, n]) => n > cap);
  const who = extra
    .map(([k, n]) => `${k} ×${n}`)
    .join("; ");
  scores.push({
    key: "rematch",
    text: extra.length
      ? `other clubs absorbed an extra rematch to make the ban possible — ${who}`
      : `no extra rematches needed to keep ${withheld.map((w) => `${w.a} vs ${w.b}`).join(", ")} off the table`,
  });
  if (extra.length) {
    for (const w of withheld) {
      diagnostics.push(
        `The rematch cap is ${cap}. Honoring ${w.a} vs ${w.b} withheld would break it — raise the cap or drop the ban.`,
      );
    }
  }
  return { scores, diagnostics };
}

export function carveHonorLines(league: League, games: PlacedGame[]): ScoreLine[] {
  if (!league.carveOuts.length) return [];
  const honored: string[] = [];
  for (const c of league.carveOuts) {
    const team = findTeam(league, c.team);
    if (!team) continue;
    const label = teamLabel(team);
    const mine = games.filter((g) => g.home === label || g.away === label);
    if (c.notAt) {
      const snap = snapCarveDate(league, c.date);
      const onDay = snap ? mine.filter((g) => g.dateIso === snap) : mine;
      const want = clock(c.notAt);
      if (onDay.length && onDay.every((g) => clock(g.kickoff) !== want)) {
        honored.push(`${label} ${carveDateShort(c)} ${c.notAt} withheld`);
      }
    }
    if (c.mustUse) {
      const want = clock(c.mustUse);
      const relevant = c.everySaturday ? mine.filter((g) => weekdayName(g.dateIso) === "saturday") : mine;
      if (relevant.length && relevant.every((g) => clock(g.kickoff) === want)) {
        honored.push(`${label} ${c.everySaturday ? "every Saturday" : carveDateShort(c)} ${c.mustUse}`);
      }
    }
  }
  return [
    {
      key: "carve-outs",
      text: `carve-outs honored: ${honored.length}${honored.length ? ` — ${honored.join("; ")}` : ""}`,
    },
  ];
}

export function carveDisplacement(league: League, prev: PlacedGame[], next: PlacedGame[]): ScoreLine[] {
  if (!league.carveOuts.length || !prev.length) return [];
  const sixPrev = prev.filter((g) => g.ageGroup === "6U");
  let sixC = 0;
  for (const g of sixPrev) {
    const n = next.find((x) => x.ageGroup === "6U" && (x.weekIso === g.weekIso || x.dateIso === g.dateIso));
    if (n && n.field !== g.field && /Field C/i.test(g.field)) sixC += 1;
  }
  const hawksPrev = prev.filter((g) => /10U Hawks/.test(g.home) || /10U Hawks/.test(g.away));
  let hawks = 0;
  let hawksLine = "10U Hawks moved from 11:15 to 1:00";
  for (const g of hawksPrev) {
    const n = next.find(
      (x) =>
        (/10U Hawks/.test(x.home) || /10U Hawks/.test(x.away)) &&
        (x.weekIso === g.weekIso || x.dateIso === g.dateIso),
    );
    if (n && n.kickoff !== g.kickoff) {
      hawks += 1;
      hawksLine = `10U Hawks moved from ${g.kickoff} to ${n.kickoff}`;
    }
  }
  return [{ key: "carve-cost", text: `6U displaced from Field C warm-up: ${sixC}; ${hawksLine}: ${hawks}` }];
}

export function mondaySixCount(games: PlacedGame[]): { monday: number; total: number } {
  const six = games.filter((g) => g.ageGroup === "6U");
  return { monday: six.filter((g) => weekdayName(g.dateIso) === "monday").length, total: six.length };
}

export function slotLockBanner(cfg: Configuration): string | undefined {
  const line = cfg.scores.find((s) => s.key === "6u-monday")?.text;
  if (!line) return undefined;
  const m = line.match(/(\d+) of (\d+)/);
  if (!m) return undefined;
  return `${m[1]} of ${m[2]} games are Monday 6:30 because of a commissioner slot lock.`;
}

export function mustUseMondayDiagnostic(league: League, games: PlacedGame[]): string | undefined {
  const lock = league.carveOuts.find((c) => c.mustUse && c.everySaturday);
  if (!lock) return undefined;
  const { monday, total } = mondaySixCount(games);
  if (!monday || !total) return undefined;
  const team = findTeam(league, lock.team);
  const label = team ? teamLabel(team) : lock.team;
  const word = monday === 1 ? "game" : "games";
  return `Honoring ${label} at ${lock.mustUse} every Saturday moved ${monday} 6U ${word} to Monday night.`;
}
